#!/usr/bin/env python3
from pathlib import Path
AVATAR=''
MARK='<!-- GABON360-AVATAR-CENTRAL-V1 -->'
PAYLOAD=r'''<!-- GABON360-AVATAR-CENTRAL-V1 -->
<style>
#g360-avatar-launch{position:fixed;left:10px;bottom:64px;z-index:100010;width:92px;height:92px;border-radius:50%;border:2px solid #35e6a0;background:#061522;box-shadow:0 0 22px #1de59a55;overflow:hidden;padding:0;cursor:pointer}
#g360-avatar-launch img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .25s}
#g360-avatar-launch.speaking img{animation:g360breath .55s infinite alternate}
@keyframes g360breath{to{transform:scale(1.035)}}
#g360-avatar-modal{display:none;position:fixed;inset:0;z-index:100020;background:#000b;align-items:center;justify-content:center;padding:12px}
#g360-avatar-card{width:min(760px,96vw);max-height:92vh;overflow:auto;background:#061522;color:#eafff5;border:1px solid #2adf9b66;border-radius:18px;padding:14px;box-shadow:0 20px 70px #000d;font:14px system-ui,sans-serif}
#g360-avatar-stage{display:flex;justify-content:center;align-items:center;position:relative;min-height:270px;background:#031019;border-radius:14px;overflow:hidden}
#g360-avatar-stage img{width:min(430px,82vw);max-height:58vh;object-fit:contain;border-radius:12px;transition:filter .2s,transform .2s}
#g360-avatar-stage.speaking img{filter:drop-shadow(0 0 18px #22e39a);animation:g360talk .45s infinite alternate}
@keyframes g360talk{to{transform:translateY(-2px) scale(1.012)}}
#g360-avatar-controls{display:flex;gap:7px;flex-wrap:wrap;margin-top:10px}
#g360-avatar-controls button{background:#10283a;color:#fff;border:1px solid #31506d;border-radius:9px;padding:8px 10px}
#g360-avatar-row{display:flex;gap:7px;margin-top:9px}
#g360-avatar-row input{flex:1;min-width:0;background:#04101a;color:#fff;border:1px solid #31506d;border-radius:9px;padding:10px}
#g360-avatar-state{margin-top:8px;color:#9fd8ff;font-size:12px}.g360-avatar-dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#18e77b;margin-right:5px}
</style>
<button id="g360-avatar-launch" aria-label="Ouvrir IA centrale"><img src="data:image/jpeg;base64,AVATAR_DATA" alt="Avatar GABON 360 AI"></button>
<div id="g360-avatar-modal"><div id="g360-avatar-card">
<div style="display:flex;justify-content:space-between;align-items:center;gap:8px"><b>🧑🏾‍💻 GABON 360 AI — IA CENTRALE</b><button id="g360-avatar-close">Fermer</button></div>
<div id="g360-avatar-stage"><img id="g360-avatar-img" src="data:image/jpeg;base64,AVATAR_DATA" alt="Avatar GABON 360 AI"></div>
<div id="g360-avatar-controls"><button id="g360-avatar-speak">🗣️ Faire parler</button><button id="g360-avatar-listen">🎙️ Écouter</button><button id="g360-avatar-stop">⏹️ Arrêter</button></div>
<div id="g360-avatar-row"><input id="g360-avatar-cmd" placeholder="Demande à l'IA : « ouvre la surveillance maritime »"><button id="g360-avatar-go">IA</button></div>
<div id="g360-avatar-state"><span class="g360-avatar-dot"></span><span id="g360-avatar-status">Prêt — avatar intégré au Centre national.</span></div>
</div></div>
<script>
(function(){
 const launch=document.getElementById('g360-avatar-launch'), modal=document.getElementById('g360-avatar-modal'), stage=document.getElementById('g360-avatar-stage'), status=document.getElementById('g360-avatar-status'), cmd=document.getElementById('g360-avatar-cmd');
 function open(){modal.style.display='flex'} function close(){modal.style.display='none'}
 function speak(text){if(!('speechSynthesis' in window)){status.textContent='Voix non disponible sur cet appareil';return} speechSynthesis.cancel(); const u=new SpeechSynthesisUtterance(text);u.lang='fr-FR';u.rate=.95;u.pitch=1;u.onstart=()=>{stage.classList.add('speaking');launch.classList.add('speaking');status.textContent='IA en train de parler';};u.onend=()=>{stage.classList.remove('speaking');launch.classList.remove('speaking');status.textContent='Prêt';};u.onerror=()=>{stage.classList.remove('speaking');launch.classList.remove('speaking');status.textContent='Voix interrompue';};speechSynthesis.speak(u)}
 function command(raw){const q=String(raw||'').trim();if(!q)return;let r=null;if(window.GABON360_HANDLE_COMMAND)r=window.GABON360_HANDLE_COMMAND(q);if(r&&r.ok){speak('J’ouvre la page demandée dans le Centre national.');}else{speak('Demande reçue. Je peux ouvrir les pages du Centre, mais je ne crée aucune alerte ni donnée sans source autorisée.')}cmd.value=''}
 launch.onclick=open;document.getElementById('g360-avatar-close').onclick=close;modal.onclick=e=>{if(e.target===modal)close()};
 document.getElementById('g360-avatar-speak').onclick=()=>speak('Bonjour Ngoua Obame. Je suis l’IA centrale de GABON 360 AI. Je suis maintenant intégrée au Centre national de situation. Je peux vous guider vers les différentes pages et vous expliquer les informations disponibles.');
 document.getElementById('g360-avatar-stop').onclick=()=>{speechSynthesis.cancel();stage.classList.remove('speaking');launch.classList.remove('speaking');status.textContent='Arrêté'};
 document.getElementById('g360-avatar-go').onclick=()=>command(cmd.value);cmd.addEventListener('keydown',e=>{if(e.key==='Enter')command(cmd.value)});
 document.getElementById('g360-avatar-listen').onclick=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR){status.textContent='Reconnaissance vocale non disponible';return}const r=new SR();r.lang='fr-FR';r.interimResults=false;r.onstart=()=>status.textContent='Écoute en cours…';r.onresult=e=>command(e.results[0][0].transcript);r.onerror=()=>status.textContent='Écoute indisponible ou interrompue';r.start()};
 document.querySelectorAll('button').forEach(b=>{if((b.textContent||'').trim()==='IA')b.addEventListener('click',open)});
 window.GABON360_AVATAR={open,close,speak,command,version:'1.0'};
})();
</script>
'''
PAYLOAD=PAYLOAD.replace('AVATAR_DATA',AVATAR)
def main():
    for p in sorted(Path('android_project').rglob('index.html'), key=lambda x:('assets' in x.parts,len(x.parts))):
        t=p.read_text(encoding='utf-8')
        if MARK in t: print('already:',p); return
        i=t.lower().rfind('</body>')
        if i>=0:
            p.write_text(t[:i]+PAYLOAD+'\n'+t[i:],encoding='utf-8'); print('injected:',p); return
    raise SystemExit('No index.html found')
if __name__=='__main__': main()
